    periodOpts:
        '\n      <div class="strip psec" data-macro-panel>\n        <div class="srow">\n          \n      <div class="cal interactive" role="button" tabindex="0" data-macro="calories" aria-expanded="false" aria-label="Calories 2,035 kcal, of 2,200 kcal, 165 kcal left. Show the meals that contributed.">\n      <div class="ring" style="--c:var(--calories);--p:0.9250" role="img" aria-label="Calories 2,035 kcal">\n        <div class="ring-track"></div>\n        <div class="ring-arc"></div>\n        <div class="ring-cap"></div>\n        <div class="ring-center"><div class="rp" style="color:var(--calories)">93%</div></div>\n      </div>\n        <div class="cal-txt">\n          <div class="cal-lab">Daily average</div>\n          <div class="cal-line">\n            <div class="cal-val">2,035<span class="cal-goal">/ 2,200</span></div>\n            <div class="cal-left">165 kcal left</div>\n          </div>\n        </div>\n      </div>\n          <div class="sgrids">\n            <div class="mgrid" style="--lc:3;--lcw:3">\n        <div class="mtile interactive" role="button" tabindex="0" data-macro="protein_g" aria-expanded="false" aria-label="Protein 148 g, of 160 g, 12 g left. Show the meals that contributed.">\n          <div class="mtop">\n            <span class="mkey">Protein</span>\n            <span class="mnum">148<span class="msub">/160<span class="munit"> g</span></span></span>\n          </div>\n          <div class="mbar"><div class="mfill" style="width:92.5%;background:var(--protein)"></div></div>\n          <div class="mcap">12 g left</div>\n        </div>\n        <div class="mtile interactive" role="button" tabindex="0" data-macro="carbs_g" aria-expanded="false" aria-label="Carbs 205 g, of 220 g, 15 g left. Show the meals that contributed.">\n          <div class="mtop">\n            <span class="mkey">Carbs</span>\n            <span class="mnum">205<span class="msub">/220<span class="munit"> g</span></span></span>\n          </div>\n          <div class="mbar"><div class="mfill" style="width:93.2%;background:var(--carbs)"></div></div>\n          <div class="mcap">15 g left</div>\n        </div>\n        <div class="mtile interactive" role="button" tabindex="0" data-macro="fat_g" aria-expanded="false" aria-label="Fat 74 g, of 70 g, 4 g over. Show the meals that contributed.">\n          <div class="mtop">\n            <span class="mkey">Fat</span>\n            <span class="mnum">74<span class="msub">/70<span class="munit"> g</span></span></span>\n          </div>\n          <div class="mbar"><div class="mfill" style="width:100.0%;background:var(--fat)"></div></div>\n          <div class="mcap">4 g over</div>\n        </div>\n            </div>\n            <div class="mgrid lim n4 psec" style="--lc:2;--lcw:4">\n        <div class="mtile interactive" role="button" tabindex="0" data-macro="sugar_g" aria-expanded="false" aria-label="Sugar 58.2 g, limit 45 g, 13.2 g over. Show the meals that contributed.">\n          <div class="mtop">\n            <span class="mkey">Sugar</span>\n            <span class="mnum" style="color:var(--over)">58.2</span>\n          </div>\n          <div class="mbar"><div class="mfill" style="width:100.0%;background:var(--sugar)"></div></div>\n          <div class="mcap">limit 45 g · 13.2 g over</div>\n        </div>\n        <div class="mtile interactive" role="button" tabindex="0" data-macro="alcohol_g" aria-expanded="false" aria-label="Alcohol 12.5 g, limit 20 g, 7.5 g under. Show the meals that contributed.">\n          <div class="mtop">\n            <span class="mkey">Alcohol</span>\n            <span class="mnum">12.5</span>\n          </div>\n          <div class="mbar"><div class="mfill" style="width:62.5%;background:var(--alcohol)"></div></div>\n          <div class="mcap">0.9 US drinks · limit 20 g</div>\n        </div>\n        <div class="mtile interactive" role="button" tabindex="0" data-macro="caffeine_mg" aria-expanded="false" aria-label="Caffeine 185 mg, limit 400 mg, 215 mg under. Show the meals that contributed.">\n          <div class="mtop">\n            <span class="mkey">Caffeine</span>\n            <span class="mnum">185</span>\n          </div>\n          <div class="mbar"><div class="mfill" style="width:46.3%;background:var(--caffeine)"></div></div>\n          <div class="mcap">limit 400 mg</div>\n        </div>\n        <div class="mtile interactive" role="button" tabindex="0" data-macro="fiber_g" aria-expanded="false" aria-label="Fiber 26.4 g, of 30 g, 3.6 g left. Show the meals that contributed.">\n          <div class="mtop">\n            <span class="mkey">Fiber</span>\n            <span class="mnum">26.4</span>\n          </div>\n          <div class="mbar"><div class="mfill" style="width:88.0%;background:var(--fiber)"></div></div>\n          <div class="mcap">of 30 g</div>\n        </div>\n        </div>\n            <div class="mhint" data-macro-hint>Tap a metric for the meals behind it</div>\n          </div>\n        </div>\n        \n      <div class="wrow psec">\n        <span class="wlab"><span class="dot" style="background:var(--water)"></span>Water</span>\n        <div class="mbar"><div class="mfill" style="width:84.0%;background:var(--water)"></div></div>\n        <span class="wnum">2.1<span class="wsub">/2.5 L</span></span>\n      </div>\n        <div class="macro-detail psec" hidden aria-live="polite"></div>\n      </div>',
